using System.ComponentModel.DataAnnotations;

namespace sv_0fba1c4da9f248f6b34a6b2debde0154.Models;

public class AppointmentFormModel
{
    // Step 1
    [Required(ErrorMessage = "Patient name is required.")]
    public string? PatientName { get; set; }

    [Required(ErrorMessage = "Email is required.")]
    [EmailAddress(ErrorMessage = "Invalid email format.")]
    public string? Email { get; set; }

    [Required(ErrorMessage = "Phone is required.")]
    public string? Phone { get; set; }

    [Required(ErrorMessage = "Insurance provider is required.")]
    public string? InsuranceProvider { get; set; }

    // Step 2
    [Required(ErrorMessage = "Please select a doctor.")]
    public string? PreferredDoctor { get; set; }

    [Required(ErrorMessage = "Date is required.")]
    public DateOnly? AppointmentDate { get; set; }

    [Required(ErrorMessage = "Please select a time slot.")]
    public string? TimeSlot { get; set; }

    [Required(ErrorMessage = "Reason for visit is required.")]
    [MaxLength(500, ErrorMessage = "Reason must be 500 characters or fewer.")]
    public string? ReasonForVisit { get; set; }
}

public class PatientValidationResult
{
    public bool IsValid => Errors.Count == 0;
    public Dictionary<string, string> Errors { get; set; } = new();
}

using sv_0fba1c4da9f248f6b34a6b2debde0154.Models;

namespace sv_0fba1c4da9f248f6b34a6b2debde0154.Services;

public interface IAppointmentService
{
    Task<List<string>> GetDoctorsAsync();
    Task<List<string>> GetAvailableTimeSlotsAsync(string doctor, DateOnly date);
    Task<PatientValidationResult> ValidatePatientAsync(AppointmentFormModel model);
}

public class AppointmentService : IAppointmentService
{
    private static readonly List<string> Doctors = new()
    {
        "Dr. Smith",
        "Dr. Johnson",
        "Dr. Patel",
        "Dr. Garcia"
    };

    private static readonly List<string> AllTimeSlots = new()
    {
        "9:00 AM",
        "9:30 AM",
        "10:00 AM",
        "10:30 AM",
        "11:00 AM",
        "1:00 PM",
        "1:30 PM",
        "2:00 PM",
        "2:30 PM",
        "3:00 PM"
    };

    public Task<List<string>> GetDoctorsAsync()
    {
        return Task.FromResult(new List<string>(Doctors));
    }

    public Task<List<string>> GetAvailableTimeSlotsAsync(string doctor, DateOnly date)
    {
        // Stub: return all slots for any doctor/date combination
        return Task.FromResult(new List<string>(AllTimeSlots));
    }

    public Task<PatientValidationResult> ValidatePatientAsync(AppointmentFormModel model)
    {
        var result = new PatientValidationResult();

        // Reject "taken@example.com" as having an outstanding balance
        if (string.Equals(model.Email, "taken@example.com", StringComparison.OrdinalIgnoreCase))
        {
            result.Errors[nameof(model.Email)] = "Account has outstanding balance.";
        }

        // Reject "None" insurance with Dr. Smith (doesn't accept self-pay)
        if (model.InsuranceProvider == "None"
            && string.Equals(model.PreferredDoctor, "Dr. Smith", StringComparison.OrdinalIgnoreCase))
        {
            result.Errors[nameof(model.PreferredDoctor)] =
                "Selected doctor does not accept self-pay patients.";
        }

        // Reject "10:00 AM" as a taken time slot (simulates race condition)
        if (model.TimeSlot == "10:00 AM")
        {
            result.Errors[nameof(model.TimeSlot)] = "This slot is no longer available.";
        }

        return Task.FromResult(result);
    }
}

@page "/book-appointment"
@rendermode InteractiveServer
@using sv_0fba1c4da9f248f6b34a6b2debde0154.Models
@using sv_0fba1c4da9f248f6b34a6b2debde0154.Services
@inject IAppointmentService AppointmentService

<PageTitle>Book Appointment</PageTitle>

<h1>Book an Appointment</h1>

<EditForm EditContext="editContext" OnValidSubmit="HandleSubmit" FormName="appointment">
    <DataAnnotationsValidator />

    @* ── Step 1: Patient Information ── *@
    <fieldset>
        <legend>Patient Information</legend>

        <div class="mb-3">
            <label class="form-label" for="patientName">Patient Name</label>
            <InputText id="patientName" class="form-control" @bind-Value="model.PatientName" />
            <ValidationMessage For="() => model.PatientName" />
        </div>

        <div class="mb-3">
            <label class="form-label" for="email">Email</label>
            <InputText id="email" class="form-control" @bind-Value="model.Email" />
            <ValidationMessage For="() => model.Email" />
        </div>

        <div class="mb-3">
            <label class="form-label" for="phone">Phone</label>
            <InputText id="phone" class="form-control" @bind-Value="model.Phone" />
            <ValidationMessage For="() => model.Phone" />
        </div>

        <div class="mb-3">
            <label class="form-label" for="insurance">Insurance Provider</label>
            <InputSelect id="insurance" class="form-select" @bind-Value="model.InsuranceProvider">
                <option value="">-- Select --</option>
                <option value="Aetna">Aetna</option>
                <option value="BlueCross">BlueCross</option>
                <option value="Cigna">Cigna</option>
                <option value="UnitedHealth">UnitedHealth</option>
                <option value="None">None</option>
            </InputSelect>
            <ValidationMessage For="() => model.InsuranceProvider" />
        </div>

        @if (!showStep2)
        {
            <button type="button" class="btn btn-primary" @onclick="ProceedToStep2">
                Next
            </button>
        }
    </fieldset>

    @* ── Step 2: Appointment Details ── *@
    @if (showStep2)
    {
        <fieldset class="mt-4">
            <legend>Appointment Details</legend>

            <div class="mb-3">
                <label class="form-label" for="doctor">Preferred Doctor</label>
                <InputSelect id="doctor" class="form-select" @bind-Value="model.PreferredDoctor">
                    <option value="">-- Select --</option>
                    @foreach (var doc in doctors)
                    {
                        <option value="@doc">@doc</option>
                    }
                </InputSelect>
                <ValidationMessage For="() => model.PreferredDoctor" />
            </div>

            <div class="mb-3">
                <label class="form-label" for="date">Date</label>
                <InputDate id="date" class="form-control" @bind-Value="model.AppointmentDate"
                           @bind-Value:after="OnDateChanged" />
                <ValidationMessage For="() => model.AppointmentDate" />
                @if (model.AppointmentDate.HasValue && model.AppointmentDate.Value <= DateOnly.FromDateTime(DateTime.Today))
                {
                    <div class="text-danger">Date must be in the future.</div>
                }
            </div>

            <div class="mb-3">
                <label class="form-label" for="timeSlot">Time Slot</label>
                <InputSelect id="timeSlot" class="form-select" @bind-Value="model.TimeSlot">
                    <option value="">-- Select --</option>
                    @foreach (var slot in timeSlots)
                    {
                        <option value="@slot">@slot</option>
                    }
                </InputSelect>
                <ValidationMessage For="() => model.TimeSlot" />
            </div>

            <div class="mb-3">
                <label class="form-label" for="reason">Reason for Visit</label>
                <InputTextArea id="reason" class="form-control" @bind-Value="model.ReasonForVisit" rows="3" />
                <ValidationMessage For="() => model.ReasonForVisit" />
            </div>

            <div class="d-flex gap-2">
                <button type="button" class="btn btn-secondary" @onclick="BackToStep1">
                    Back
                </button>
                <button type="button" class="btn btn-info" @onclick="CheckAvailability" disabled="@isChecking">
                    @(isChecking ? "Checking…" : "Check Availability")
                </button>
                <button type="submit" class="btn btn-success" disabled="@(!availabilityConfirmed)">
                    Book Appointment
                </button>
            </div>
        </fieldset>
    }
</EditForm>

@if (submitted)
{
    <div class="alert alert-success mt-4">
        Appointment booked successfully for <strong>@model.PatientName</strong>
        with <strong>@model.PreferredDoctor</strong>
        on @model.AppointmentDate?.ToString("MMM dd, yyyy") at @model.TimeSlot.
    </div>
}

@code {
    private AppointmentFormModel model = new();
    private EditContext editContext = default!;
    private ValidationMessageStore serverMessageStore = default!;

    private List<string> doctors = new();
    private List<string> timeSlots = new();

    private bool showStep2;
    private bool isChecking;
    private bool availabilityConfirmed;
    private bool submitted;

    private static readonly string[] Step1Fields =
    {
        nameof(AppointmentFormModel.PatientName),
        nameof(AppointmentFormModel.Email),
        nameof(AppointmentFormModel.Phone),
        nameof(AppointmentFormModel.InsuranceProvider)
    };

    protected override void OnInitialized()
    {
        editContext = new EditContext(model);
        serverMessageStore = new ValidationMessageStore(editContext);

        // Clear server errors when the user edits any field
        editContext.OnFieldChanged += (_, args) =>
        {
            serverMessageStore.Clear(args.FieldIdentifier);
            availabilityConfirmed = false;
            editContext.NotifyValidationStateChanged();
        };
    }

    private async Task ProceedToStep2()
    {
        serverMessageStore.Clear();

        // Validate only step-1 fields
        var isStep1Valid = true;
        foreach (var field in Step1Fields)
        {
            var fi = editContext.Field(field);
            if (!editContext.IsValid(fi))
                isStep1Valid = false;
        }

        // Trigger validation so messages appear
        editContext.Validate();

        if (!isStep1Valid)
            return;

        doctors = await AppointmentService.GetDoctorsAsync();
        showStep2 = true;
    }

    private void BackToStep1()
    {
        showStep2 = false;
        availabilityConfirmed = false;
    }

    private async Task OnDateChanged()
    {
        timeSlots = new();
        model.TimeSlot = null;
        availabilityConfirmed = false;

        if (!string.IsNullOrEmpty(model.PreferredDoctor) && model.AppointmentDate.HasValue)
        {
            timeSlots = await AppointmentService.GetAvailableTimeSlotsAsync(
                model.PreferredDoctor, model.AppointmentDate.Value);
        }
    }

    private async Task CheckAvailability()
    {
        serverMessageStore.Clear();
        editContext.NotifyValidationStateChanged();

        // Run DataAnnotations validation first
        if (!editContext.Validate())
            return;

        // Custom: date must be in the future
        if (model.AppointmentDate.HasValue
            && model.AppointmentDate.Value <= DateOnly.FromDateTime(DateTime.Today))
        {
            serverMessageStore.Add(
                editContext.Field(nameof(model.AppointmentDate)),
                "Date must be in the future.");
            editContext.NotifyValidationStateChanged();
            return;
        }

        isChecking = true;

        try
        {
            var result = await AppointmentService.ValidatePatientAsync(model);

            if (!result.IsValid)
            {
                foreach (var (field, message) in result.Errors)
                {
                    serverMessageStore.Add(editContext.Field(field), message);
                }

                editContext.NotifyValidationStateChanged();
                availabilityConfirmed = false;
            }
            else
            {
                availabilityConfirmed = true;
            }
        }
        finally
        {
            isChecking = false;
        }
    }

    private void HandleSubmit()
    {
        if (!availabilityConfirmed)
            return;

        submitted = true;
    }
}

