+                <ValidationMessage For="() => model.TimeSlot" />
+            </div>
+
+            <div class="mb-3">
+                <label class="form-label" for="reason">Reason for Visit</label>
+                <InputTextArea id="reason" class="form-control" @bind-Value="model.ReasonForVisit" rows="3" />
+                <ValidationMessage For="() => model.ReasonForVisit" />
+            </div>
+
+            <div class="d-flex gap-2">
+                <button type="button" class="btn btn-secondary" @onclick="BackToStep1">
+                    Back
+                </button>
+                <button type="button" class="btn btn-info" @onclick="CheckAvailability" disabled="@isChecking">
+                    @(isChecking ? "Checking…" : "Check Availability")
+                </button>
+                <button type="submit" class="btn btn-success" disabled="@(!availabilityConfirmed)">
+                    Book Appointment
+                </button>
+            </div>
+        </fieldset>
+    }
+</EditForm>
+
+@if (submitted)
+{
+    <div class="alert alert-success mt-4">
+        Appointment booked successfully for <strong>@model.PatientName</strong>
+        with <strong>@model.PreferredDoctor</strong>
+        on @model.AppointmentDate?.ToString("MMM dd, yyyy") at @model.TimeSlot.
+    </div>
+}
+
+@code {
+    private AppointmentFormModel model = new();
+    private EditContext editContext = default!;
+    private ValidationMessageStore serverMessageStore = default!;
+
+    private List<string> doctors = new();
+    private List<string> timeSlots = new();
+
+    private bool showStep2;
+    private bool isChecking;
+    private bool availabilityConfirmed;
+    private bool submitted;
+
+    private static readonly string[] Step1Fields =
+    {
+        nameof(AppointmentFormModel.PatientName),
+        nameof(AppointmentFormModel.Email),
+        nameof(AppointmentFormModel.Phone),
+        nameof(AppointmentFormModel.InsuranceProvider)
+    };
+
+    protected override void OnInitialized()
+    {
+        editContext = new EditContext(model);
+        serverMessageStore = new ValidationMessageStore(editContext);
+
+        // Clear server errors when the user edits any field
+        editContext.OnFieldChanged += (_, args) =>
+        {
+            serverMessageStore.Clear(args.FieldIdentifier);
+            availabilityConfirmed = false;
+            editContext.NotifyValidationStateChanged();
+        };
+    }
+
+    private async Task ProceedToStep2()
+    {
+        serverMessageStore.Clear();
+
+        // Validate only step-1 fields
+        var isStep1Valid = true;
+        foreach (var field in Step1Fields)
+        {
+            var fi = editContext.Field(field);
+            if (!editContext.IsValid(fi))
+                isStep1Valid = false;
+        }
+
+        // Trigger validation so messages appear
+        editContext.Validate();
+
+        if (!isStep1Valid)
+            return;
+
+        doctors = await AppointmentService.GetDoctorsAsync();
+        showStep2 = true;
+    }
+
+    private void BackToStep1()
+    {
+        showStep2 = false;
+        availabilityConfirmed = false;
+    }
+
+    private async Task OnDateChanged()
+    {
+        timeSlots = new();
+        model.TimeSlot = null;
+        availabilityConfirmed = false;
+
+        if (!string.IsNullOrEmpty(model.PreferredDoctor) && model.AppointmentDate.HasValue)
+        {
+            timeSlots = await AppointmentService.GetAvailableTimeSlotsAsync(
+                model.PreferredDoctor, model.AppointmentDate.Value);
+        }
+    }
+
+    private async Task CheckAvailability()
+    {
+        serverMessageStore.Clear();
+        editContext.NotifyValidationStateChanged();
+
+        // Run DataAnnotations validation first
+        if (!editContext.Validate())
+            return;
+
+        // Custom: date must be in the future
+        if (model.AppointmentDate.HasValue
+            && model.AppointmentDate.Value <= DateOnly.FromDateTime(DateTime.Today))
+        {
+            serverMessageStore.Add(
+                editContext.Field(nameof(model.AppointmentDate)),
+                "Date must be in the future.");
+            editContext.NotifyValidationStateChanged();
+            return;
+        }
+
+        isChecking = true;
+
+        try
+        {
+            var result = await AppointmentService.ValidatePatientAsync(model);
+
+            if (!result.IsValid)
+            {
+                foreach (var (field, message) in result.Errors)
+                {
+                    serverMessageStore.Add(editContext.Field(field), message);
+                }
+
+                editContext.NotifyValidationStateChanged();
+                availabilityConfirmed = false;
+            }
+            else
+            {
+                availabilityConfirmed = true;
+            }
+        }
+        finally
+        {
+            isChecking = false;
+        }
+    }
+
+    private void HandleSubmit()
+    {
+        if (!availabilityConfirmed)
+            return;
+
+        submitted = true;
+    }
+}
+

